/* Example: basic grid layout and child styling */
.container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    padding: 20px;
}

.child {
    width: 100px;
    height: 100px;
    border: 2px solid #ccc;
    border-radius: 8px;
}

/* Example: applying a conic-gradient to an element */
.element {
    background: conic-gradient(red, blue);
}

/* Example of a conic-gradient with multiple color stops */
.gradient-circle {
    background: conic-gradient(red, yellow, green, blue);
}

/* Example: conic-gradient with percentage stops */
.element {
    background: conic-gradient(red 0%, yellow 25%, green 50%, blue 100%);
}

/* Example of repeating-conic-gradient pattern */
.repeating-example {
    background: repeating-conic-gradient(red 0deg 10deg, blue 10deg 20deg);
}

/* Example: making a square element circular */
.square {
  width: 100px;
  height: 100px;
  border-radius: 50%;
}

/* Example pie chart with three segments */
.pie-chart {
    width: 200px;
    height: 200px;
    background: conic-gradient(red 0% 30%, blue 30% 70%, green 70% 100%);
    border-radius: 50%;
}

/* Example of a different conic-gradient pattern */
.gradient-box-2 {
    width: 200px;
    height: 200px;
    background: conic-gradient(from 45deg, red 0deg 90deg, blue 90deg 180deg, green 180deg 270deg, yellow 270deg 360deg);
}
